public ListNode? RemoveElementsRebuild(ListNode? head, int val)
{
    ListNode dummy = new ListNode(0);
    ListNode tail = dummy;
    while (head != null)
    {
        if (head.Val != val)
        {
            tail.Next = new ListNode(head.Val);
            tail = tail.Next;
        }
        head = head.Next;
    }
    return dummy.Next;
}

public ListNode? RemoveElements(ListNode? head, int val)
{
    ListNode dummy = new ListNode(0);
    dummy.Next = head;
    ListNode prev = dummy;
    while (head != null)
    {
        if (head.Val == val)
            prev.Next = head.Next;
        else
            prev = head;
        head = head.Next;
    }
    return dummy.Next;
}
